mapper.select:
SELECT A.COM_NAME_LOC AS COM_NAME, A.IRS_NO AS IRS_NO, A.CEO_NAME_LOC AS CEO_NAME, A.ADD_DATE, (SELECT SG_NAME FROM KEPSGMG WHERE SG_ID = B.ITMG1_CD) AS SG_NAME, B.KEP_DAMDANG_NM AS KEP_USER_NAME, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = B.CONFIRM1_USER_ID) AS CONFIRM1_USER_NAME, DECODE(NVL(B.BUYER_HO_YN,'N'),'N','없음','Y','있음','오류') AS BUYER_HO_TEXT, A.COM_CODE, B.ITMG1_CD, B.KEP_DAMDANG_NM AS KEP_DAMDANG_ID, B.CONFIRM1_USER_ID, NVL(B.BUYER_HO_YN,'N') AS BUYER_HO_YN, NVL(DECODE(SUBSTR(A.IRS_NO,5,2),'85',A.CORP_REG_NO,A.IRS_NO),A.IRS_NO) AS WIDUS, B.SP_TYPE, DECODE(B.SP_TYPE,'N','정규','T','임시','A','옥션') AS SP_TYPE_TEXT, A.CREDIT_STATUS, DECODE(A.CREDIT_STATUS,'A','B-이상','B','등급미달','C','면제','N','미평가') AS CREDIT_STATUS_TEXT, A.CREDIT_RATING, A.CREDIT_EXPIRE_DATE, B.CONFIRM1_DATE FROM ICOMCMPY A, SUPLINFO2 B WHERE A.COM_CODE = B.SUPPLIER AND A.STATUS = 'T'
AND A.COM_NAME_LOC LIKE '%' || #{st_com_name} || '%'
AND B.KEP_DAMDANG_NM LIKE #{st_kep_damdang_id}||'%'
AND A.IRS_NO = #{st_irs_no}
AND NVL(A.CREDIT_STATUS, 'N') = #{st_credit_status}
AND B.SP_TYPE = #{st_sp_type}
ORDER BY B.CONFIRM1_DATE||B.CONFIRM1_TIME
